// LeadFlow Free - step 1: your leads (synthetic sample rows).
// Quick start: press "Execute workflow" and open the "Summarize patterns" node.
// For your own data, replace the rows below (keep first_name, last_name, domain),
// or swap this node for "Read/Write Files from Disk" + "Extract from File" (CSV).
const leads = [
  { first_name: 'Ana', last_name: 'Kovač', domain: 'primastudio.rs', company: 'Prima Studio' },
  { first_name: 'Đorđe', last_name: 'Šišić', domain: 'example.com', company: 'Example' },
  { first_name: 'Jürgen', last_name: 'Müller', domain: 'muller-gmbh.de', company: 'Muller GmbH' },
  { first_name: '', last_name: 'Petrović', domain: 'petroco.rs', company: 'Petro Co' },
  { first_name: 'Sara', last_name: 'Alić', domain: 'www.alfa.rs', company: 'Alfa' }
];
return leads.map((lead) => ({ json: lead }));

// LeadFlow Free - step 2: candidate patterns per lead, accents folded first.
// Folding BEFORE stripping means "Kovač" becomes "kovac", not "kovac" + a stray dot.
// German umlauts expand to two letters (Müller -> mueller), which is how most
// companies spell those addresses. Every other accent is dropped after decomposing.
// One item per lead in, one item per lead out: a lead that cannot produce an address
// is reported in skipped_reason instead of silently disappearing from the run.
const fold = { 'ä': 'ae', 'ö': 'oe', 'ü': 'ue', 'đ': 'dj', 'ø': 'o', 'ł': 'l', 'ß': 'ss', 'æ': 'ae', 'œ': 'oe', 'þ': 'th', 'ð': 'd', 'ı': 'i' };
function normalize(value) {
  return String(value === undefined || value === null ? '' : value)
    .toLowerCase()
    .split('')
    .map((c) => (fold[c] === undefined ? c : fold[c]))
    .join('')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z]/g, '');
}
const rows = $input.all().map((item) => item.json);
const out = [];
for (const row of rows) {
  const first = normalize(row.first_name);
  const last = normalize(row.last_name);
  const domain = String(row.domain === undefined || row.domain === null ? '' : row.domain)
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/.*$/, '')
    .trim();
  const lead = {
    first_name: row.first_name || '',
    last_name: row.last_name || '',
    company: row.company || '',
    domain,
  };
  if (!domain) {
    out.push({ json: { lead, patterns: [], skipped_reason: 'no domain: add the company website (e.g. alfa.rs) to this lead' } });
    continue;
  }
  const candidates = [];
  if (first && last) {
    candidates.push(first + '.' + last, first + last, first.charAt(0) + '.' + last, first.charAt(0) + last);
  }
  if (first) candidates.push(first);
  if (!first && last) candidates.push(last);
  const seen = new Set();
  const patterns = [];
  for (const pattern of candidates) {
    if (!pattern || pattern.charAt(0) === '.' || pattern.charAt(pattern.length - 1) === '.' || seen.has(pattern)) continue;
    seen.add(pattern);
    patterns.push({
      email: pattern + '@' + domain,
      pattern: pattern,
      first_name: lead.first_name,
      last_name: lead.last_name,
      company: lead.company,
    });
  }
  out.push({ json: { lead, patterns } });
}
return out;

// LeadFlow Free - step 3: one honest summary of the run (no invented match rates).
// Leads that could not produce an address are listed with a reason, so nothing in the
// input disappears without explanation.
const items = $input.all().map((item) => item.json);
const patterns = [];
const skipped = [];
for (const item of items) {
  for (const p of item.patterns || []) patterns.push(p);
  if (item.skipped_reason) skipped.push({ ...(item.lead || {}), reason: item.skipped_reason });
}
const domains = new Set(patterns.map((row) => String(row.email).split('@')[1]));
return [{
  json: {
    leads_in: items.length,
    patterns_out: patterns.length,
    domains_covered: domains.size,
    skipped,
    note: 'Candidate addresses only. Verify before sending. No API, no credentials, no data left this instance.' +
      (skipped.length ? ' ' + skipped.length + ' lead(s) skipped for a missing domain - see skipped.' : ''),
    patterns,
  },
}];
